class Solution {public:int minCostToEqualizeArray(vector<int>& nums,int cost1,int cost2){
 const long long MOD=1000000007;int n=nums.size();long long mn=*min_element(nums.begin(),nums.end()),mx=*max_element(nums.begin(),nums.end()),sum=accumulate(nums.begin(),nums.end(),0LL);
 if(n<=2||2LL*cost1<=cost2){long long v=mx*n-sum;return (int)(v*cost1%MOD);}
 auto calc=[&](long long t){long long total=t*n-sum,largest=t-mn;long long pairs=min(total/2,total-largest);return pairs*cost2+(total-2*pairs)*cost1;};
 long long best=calc(mx);long long threshold=max(mx,(sum-2*mn+n-3)/(n-2));
 for(long long t=mx;t<=mx+2;++t)best=min(best,calc(t));
 for(long long t=max(mx,threshold-2);t<=threshold+2;++t)best=min(best,calc(t));
 return (int)(best%MOD);
}};
